1	package release
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sync"
10		"syscall"
11	)
12	
13	const (
14		stateFileName = "ledger.json"
15		lockFileName  = "ledger.lock"
16		stateVersion  = 1
17	)
18	
19	// Store 是一个本地配方批次台账，数据保存在调用方指定的目录中。
20	// 不同目录互相独立；多个 Store 可以安全并发提交（进程内互斥、进程间文件锁）。
21	type Store struct {
22		// dir 是打开时确定的绝对路径。即使传入相对目录，也在 Open 时按当时的
23		// 工作目录解析并固定下来：此后调用方切换进程工作目录，本对象的读取与
24		// 保存仍指向最初打开的位置，绝不会按新工作目录重新解释这个相对路径。
25		dir      string
26		lockFile *os.File
27		mu       sync.Mutex
28		state    *persistedState
29	}
30	
31	// Open 打开（或首次使用）位于 dir 的台账。
32	// 目录不存在时会创建；目录中没有台账文件时得到空台账；
33	// 台账文件已存在但没有任何内容（零字节，无论原本就是空文件还是使用中被截断）
34	// 时按损坏处理；已有台账文件无法读取、解析，存在两条配方编号与版本号
35	// 完全相同的配方记录，存在两条批次编号完全相同的批次记录，
36	// 任一已保存配方版本不包含任何物料（物料列表为空数组、null 或字段缺失，
37	// 即使名称、编号、版本号齐全且内容能正常解析；含尚未被任何批次引用的版本），
38	// 任一配方版本的任一物料每份克数不是正数，
39	// 任一配方版本内同一物料编号出现多次，
40	// 任一批次绑定的配方版本未登记，
41	// 任一批次的状态不是精确的 "draft"、"executing"、"closed" 之一
42	// （缺失、为空、null、其他字符串，或大小写、前后空格与合法值不同），
43	// 任一批次的计划份数不是正整数，或按其绑定的配方版本计算时某物料的
44	// 应投量（每份克数 × 计划份数）无法精确表示到千分之一克或超过
45	// 9223372036854775.807 克，
46	// 任一批次仍为草稿状态却带有投料记录，
47	// 任一批次已保存投料的登记序号与记录在列表中的位置不一致
48	// （第一条不为 1、零或负数、重号、漏号、跳号，或调换记录位置后
49	// 未同步序号；不同物料共用批次序号、不同批次各自从 1 开始），
50	// 已保存投料的物料编号不属于该批次绑定的配方版本，
51	// 或已保存的投料数量非法（单条不是正数，或同一批次同一物料累计实投
52	// 超过 9223372036854775.807 克），
53	// 或任一已保存的成功投料请求的结果缺失、为 null、为空对象，或其登记
54	// 序号在原请求对应的批次中不存在，或结果的物料编号、实际克数、投料
55	// 时间（同一时刻不区分时区写法）、登记人与该序号的实际投料或原提交
56	// 内容不一致（其他批次的同序号投料不能作为对应记录，原批次不存在时
57	// 保存的结果不能单独作为登记成功的依据）时，返回 ErrCorruptData（可用
58	// errors.Is 判断），不会当成空台账继续保存，也不会返回可继续使用的
59	// 台账对象。
60	//
61	// dir 可以是相对目录：其位置只按 Open 调用时的工作目录解析一次并固定。
62	// 打开之后即使进程切换了工作目录，本对象的查询与保存仍始终指向最初打开
63	// 的目录，不会按新工作目录重新解释相对路径；台账操作本身也不会改变调用
64	// 方的工作目录。切换工作目录后另行 Open 同一相对目录，得到的是绑定新位
65	// 置的独立对象，与此前的对象互不影响。
66	func Open(dir string) (*Store, error) {
67		if dir == "" {
68			return nil, errors.New("数据位置不能为空")
69		}
70		// 先按“打开那一刻”的工作目录把位置解析成绝对路径并固定。后续每次
71		// 查询与写入都会重新读取台账文件，若仍持有相对路径，调用方一旦切换
72		// 工作目录，相对路径就会指向别处——可能把已登记批次查成不存在，或把
73		// 变更读写到另一个同名台账。解析为绝对路径后，本对象始终绑定最初打
74		// 开的位置。filepath.Abs 只做词法解析、不访问文件系统，目录尚不存在
75		// （首次使用会自动创建）时也能得到稳定结果。
76		absDir, err := filepath.Abs(dir)
77		if err != nil {
78			return nil, fmt.Errorf("解析数据位置 %q 失败: %w", dir, err)
79		}
80		if err := os.MkdirAll(absDir, 0o755); err != nil {
81			return nil, fmt.Errorf("创建数据位置 %q 失败: %w", absDir, err)
82		}
83		info, err := os.Stat(absDir)
84		if err != nil {
85			return nil, fmt.Errorf("读取数据位置 %q 失败: %w", absDir, err)
86		}
87		if !info.IsDir() {
88			return nil, fmt.Errorf("数据位置 %q 不是目录", absDir)
89		}
90	
91		lockPath := filepath.Join(absDir, lockFileName)
92		lf, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
93		if err != nil {
94			return nil, fmt.Errorf("打开锁文件失败: %w", err)
95		}
96	
97		s := &Store{dir: absDir, lockFile: lf}
98		if err := s.load(); err != nil {
99			lf.Close()
100			return nil, err
101		}
102		return s, nil
103	}
104	
105	// Close 释放台账占用的文件锁。
106	func (s *Store) Close() error {
107		s.mu.Lock()
108		defer s.mu.Unlock()
109		if s.lockFile == nil {
110			return nil
111		}
112		err := s.lockFile.Close()
113		s.lockFile = nil
114		return err
115	}
116	
117	func (s *Store) lockExclusive() error {
118		if s.lockFile == nil {
119			return errors.New("台账已关闭")
120		}
121		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_EX); err != nil {
122			return fmt.Errorf("锁定台账失败: %w", err)
123		}
124		return nil
125	}
126	
127	func (s *Store) lockShared() error {
128		if s.lockFile == nil {
129			return errors.New("台账已关闭")
130		}
131		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_SH); err != nil {
132			return fmt.Errorf("锁定台账失败: %w", err)
133		}
134		return nil
135	}
136	
137	func (s *Store) unlock() {
138		_ = syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_UN)
139	}
140	
141	func (s *Store) load() error {
142		data, err := os.ReadFile(filepath.Join(s.dir, stateFileName))
143		if err != nil {
144			if os.IsNotExist(err) {
145				s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
146				return nil
147			}
148			return fmt.Errorf("%w: 读取台账文件失败: %v", ErrCorruptData, err)
149		}
150		if len(data) == 0 {
151			// 区分“没有台账文件”与“已有文件但内容为空”：文件不存在才算首次使用，
152			// 零字节文件（原本就为空或使用中被截断）一律按损坏处理——既不能当成
153			// 空台账补写，也不能凭内存中的旧记录还原，调用方必须明确知道无法读取。
154			return fmt.Errorf("%w: 台账文件 %q 没有内容", ErrCorruptData, filepath.Join(s.dir, stateFileName))
155		}
156		var st persistedState
157		if err := json.Unmarshal(data, &st); err != nil {
158			return fmt.Errorf("%w: 台账文件解析失败: %v", ErrCorruptData, err)
159		}
160		if st.Version != stateVersion {
161			return fmt.Errorf("%w: 台账版本 %d 不受支持", ErrCorruptData, st.Version)
162		}
163		if err := validateState(&st); err != nil {
164			return err
165		}
166		if st.Requests == nil {
167			st.Requests = map[string]*requestRecord{}
168		}
169		s.state = &st
170		return nil
171	}
172	
173	// validateState 检查台账的引用完整性与数量合法性：
174	//   - 配方由配方编号与版本号共同识别，同一台账内每组编号+版本号只能
175	//     对应一条配方记录。只要同组出现第二条记录，无论名称、物料、每份克数
176	//     是否相同（即使内容完全一致），整份台账即视为损坏：不能挑第一条或
177	//     最后一条、不能合并物料、也不能自行删除一条后继续——重复记录会让
178	//     查询结果与批次的应投依据取决于文件中的排列顺序。重复版本即使尚未
179	//     被任何批次引用也一样拒绝，其他配方与批次完整也不能放行本次读取。
180	//   - 批次由批次编号唯一识别，同一台账内一个编号只能对应一条批次记录。
181	//     同一编号出现第二条记录，无论绑定的配方版本、计划份数、状态是否
182	//     相同（即使内容完全一致），整份台账即视为损坏：不能挑第一条或最后
183	//     一条、不能合并投料、不能自动改号或删除一条后继续——重复记录会让
184	//     同一编号查到的配方、投料与数量核对取决于文件中的排列顺序。其他
185	//     批次完整、投料数量吻合，或调用方只想查看另一个正常批次，都不能
186	//     放行本次读取；不同编号的批次绑定同一配方版本不受影响。
187	//   - 每个已保存配方版本必须至少包含一种物料——与登记配方时的规则一致。
188	//     物料列表保存成空数组、null 或字段缺失，解析后都是空列表，属于同一
189	//     种损坏：没有物料就没有任何用量依据，采用它的批次得不到任何数量核对项。
190	//     任一版本（包括尚未被任何批次使用的版本）没有物料，整份台账即视为
191	//     损坏，即使其名称、编号与版本号齐全、台账内容能正常解析也不能接受：
192	//     不能补造物料、不能删除问题版本，也不能用同一配方编号下的其他完整
193	//     版本顶替。其他配方与批次完整、调用方只查询正常记录，或采用该版本
194	//     的批次份数为正、状态合法且尚未投料（没有任何数量差额），都不能放行。
195	//     没有登记任何配方的空台账与此不同，仍按空台账正常使用。
196	//   - 每个配方版本的每种物料，每份克数必须是正数——与登记时的规则一致。
197	//     任一版本（包括尚未被任何批次使用的版本）的任一物料为零或负数，
198	//     整份台账即视为损坏：不能改成最小用量、取绝对值、删除问题物料
199	//     或改用其他版本后继续，其他配方完整或批次数量恰好吻合也不能放行。
200	//   - 同一配方版本的物料列表内，每个物料编号只能出现一次——与登记时的
201	//     规则一致。任一版本（包括尚未被任何批次使用的版本）内同一物料编号
202	//     出现多次，整份台账即视为损坏：不能合并重复项、相加克数、丢弃其中
203	//     一条或由查询者挑一项作为依据，即使两条克数完全相同也不能放行；
204	//     不同版本、不同配方各自使用同一物料编号不受影响。
205	//   - 每个批次记录的配方编号与版本号必须共同指向一个已登记的配方版本。
206	//     任一批次找不到对应版本，整份台账即视为损坏——不能改用同编号的其他版本，
207	//     也不能按名称或物料内容替换，即使其他批次仍然完整也不能放行本次读取。
208	//   - 每个已保存批次的计划份数必须为正整数，且按该批次实际绑定的配方版本
209	//     计算，每种物料的应投量（每份克数 × 计划份数）都必须能精确表示到
210	//     千分之一克、且不超过 maxGramsMilli（9223372036854775.807 克）。
211	//     任一批次份数为零或负数，或任一物料的应投量无法精确表示/超出上限，
212	//     整份台账即视为损坏：不区分草稿、执行中还是已关闭，也不取决于本次
213	//     查询哪个批次——不能自动减少份数、改选其他配方版本或删除问题批次，
214	//     即使其他批次完整也不能放行。上限按每种物料分别判断：多种物料的
215	//     应投量相加超过上限不构成非法，单种物料恰好等于上限仍合法。
216	//   - 每个已保存批次的状态必须精确对应 draft、executing、closed 三个
217	//     字符串之一。状态字段缺失、为空或为 null，或保存成 "ready" 等其他
218	//     字符串，整份台账即视为损坏：不做大小写归一化，也不去除前后空格，
219	//     "Draft"、" draft " 与空字符串一样不合法。不能根据该批次有没有投料
220	//     替它猜一个状态、不能补成草稿，也不能删除该批次或跳过它继续返回
221	//     其他批次与配方——状态无法识别时，草稿带投料、状态机准入、查询
222	//     视图等所有依赖状态的规则都无从套用。即使配方版本与计划份数都正常、
223	//     尚未投料或投料数量恰好吻合，也不能放行；其他批次完整或本次只查询
224	//     别的批次、配方同样不能绕过。
225	//   - 草稿批次不能带有任何投料记录：登记投料只允许操作执行中的批次，
226	//     草稿尚未开始执行，出现投料说明保存内容自相矛盾。任一草稿批次包含
227	//     至少一条投料，整份台账即视为损坏——即使这些投料的物料都属于绑定
228	//     版本、克数均为合法正数、累计实投恰好等于应投，也不能接受；不能
229	//     丢弃投料后当作干净草稿，不能把批次自动改为执行中或已关闭，也不
230	//     能替调用方改选配方版本来继续读取。台账里另有正常批次、调用方只
231	//     查询其他配方或批次，都不能绕过这项矛盾。没有投料的草稿不受影响；
232	//     执行中尚未投料、已关闭批次没有投料或仍有欠投超投都属正常。
233	//   - 每条已保存的投料数量必须是正数；同一批次内同一物料的累计实投
234	//     不得超过 maxGramsMilli（9223372036854775.807 克）。任一记录为零或
235	//     负数，或任一物料累计超限，整份台账即视为损坏——负数记录即使能被
236	//     正数抵消回范围内也不接受，超限也不能截断或忽略后继续。
237	//   - 每个批次的投料按保存位置共用一条从 1 开始的登记序列：第一条序号
238	//     必须为 1，此后每条依次加 1，且保存序号必须与该记录在列表中的位置
239	//     一致。不同物料的投料共用同一序列、不按物料各自编号；不同批次各自
240	//     从 1 开始。任一条记录的序号为零或负数、与前一条不连续（漏号、
241	//     跳号）、与其他记录重号，或记录调换了位置却未同步序号，整份台账即
242	//     视为损坏：即使物料归属与数量全部合法也不能接受，不能按自带序号或
243	//     投料时间重排、不能补号、不能删除问题记录后继续。投料时间由调用方
244	//     填写、从不参与排序，时间相同或乱序不能作为序号有误的依据。空投料
245	//     列表不构成序号错误，仍按批次状态规则处理。
246	//   - 每条已保存投料的物料编号必须属于该批次绑定的配方版本。归属以批次
247	//     实际绑定的版本为准：物料只出现在同编号的其他版本或其他配方中，
248	//     不能作为接受依据；也不能改选版本、补入物料或丢弃问题投料后继续。
249	func validateState(st *persistedState) error {
250		// 先按“配方编号 + 版本号”唯一标识遍历全部配方记录：同组出现第二条
251		// 记录即数据损坏，必须先于一切按标识查找的校验拒绝——否则重复记录
252		// 会让 findRecipe 总是返回排在前面的一条，查询结果与批次应投依据都
253		// 取决于文件排列顺序。完全相同的内容也不是合法重复。
254		versions := make(map[recipeKey]bool, len(st.Recipes))
255		for _, r := range st.Recipes {
256			if r == nil {
257				return fmt.Errorf("%w: 台账中存在空的配方记录", ErrCorruptData)
258			}
259			key := recipeKey{r.RecipeNo, r.Version}
260			if versions[key] {
261				return fmt.Errorf("%w: 配方编号 %q 版本号 %q 的配方记录重复",
262					ErrCorruptData, r.RecipeNo, r.Version)
263			}
264			versions[key] = true
265		}
266		for _, r := range st.Recipes {
267			// 每个已保存配方版本必须至少包含一种物料——与登记配方时的规则一致：
268			// 没有物料就没有任何用量依据，采用它的批次得不到任何数量核对项。
269			// 物料列表保存成空数组、null 或字段缺失，解析后都是空列表，属于同一
270			// 种损坏。即使名称、编号、版本号齐全且台账内容能正常解析，也不能把
271			// 该版本当作有效配方：不能补造物料、不能删除问题版本，也不能改用同一
272			// 配方编号下的其他完整版本顶替。该校验针对所有已保存版本，包括尚未
273			// 被任何批次引用的版本；台账中另有正常配方与批次，或调用方只查询正常
274			// 记录，都不能绕过。必须先于逐条物料的校验判断——没有物料时，物料
275			// 编号重复与每份克数规则都无从套用。
276			if len(r.Materials) == 0 {
277				return fmt.Errorf("%w: 配方编号 %q 版本号 %q 的配方版本没有物料，每个配方版本必须至少包含一种物料",
278					ErrCorruptData, r.RecipeNo, r.Version)
279			}
280			seen := make(map[string]bool, len(r.Materials))
281			for _, m := range r.Materials {
282				if seen[m.MaterialNo] {
283					return fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
284						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
285				}
286				seen[m.MaterialNo] = true
287				if m.GramsMilli <= 0 {
288					return fmt.Errorf("%w: 配方 %q 版本 %q 物料 %q 的每份克数不是正数",
289						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
290				}
291			}
292		}
293		// 再按批次编号唯一标识遍历全部批次记录：同一编号出现第二条记录即数据
294		// 损坏，必须先于一切按编号查找的校验拒绝——否则 findBatch 总是返回排在
295		// 前面的一条，同一编号查到的配方、投料与数量核对都取决于文件排列顺序。
296		// 两条记录即使绑定不同配方版本、计划份数不同或状态不同也属于重复；
297		// 内容完全一致同样不是合法记录。不能挑第一条或最后一条、不能合并投料、
298		// 也不能自动改号或删除一条后继续。不同批次绑定同一配方版本不受影响。
299		batchNos := make(map[string]bool, len(st.Batches))
300		for _, b := range st.Batches {
301			if b == nil {
302				return fmt.Errorf("%w: 台账中存在空的批次记录", ErrCorruptData)
303			}
304			if batchNos[b.BatchNo] {
305				return fmt.Errorf("%w: 批次编号 %q 的批次记录重复", ErrCorruptData, b.BatchNo)
306			}
307			batchNos[b.BatchNo] = true
308		}
309		for _, b := range st.Batches {
310			// 状态必须精确对应 draft、executing、closed 之一，且必须先于一切
311			// 依赖状态语义的校验（草稿带投料、状态机操作、查询视图）判断：
312			// 无法识别的状态没有任何既有规则可以套用。缺失、为空、null、写成
313			// "ready" 等其他字符串，或大小写不同、前后多了空格，都不能自动
314			// 当成某个合法状态——不能按是否已有投料替它猜状态，不能补成草稿，
315			// 也不能删除该批次后继续。只要一个批次状态不合法，整份台账即视为
316			// 损坏：其他批次与配方完整、本次只想查询别的批次或配方，都不能放行。
317			if !isValidBatchStatus(b.Status) {
318				if b.Status == "" {
319					return fmt.Errorf("%w: 批次 %q 的状态为空或缺失，必须是 %q、%q 或 %q 之一",
320						ErrCorruptData, b.BatchNo, StatusDraft, StatusExecuting, StatusClosed)
321				}
322				return fmt.Errorf("%w: 批次 %q 的状态 %q 无法识别，必须精确为 %q、%q 或 %q 之一（大小写或前后空格不同也不合法）",
323					ErrCorruptData, b.BatchNo, b.Status, StatusDraft, StatusExecuting, StatusClosed)
324			}
325			// 草稿尚未开始执行，不能登记投料；已保存的草稿却带着投料，
326			// 说明记录自相矛盾。必须先于配方归属与数量校验拒绝——否则
327			// 这份草稿还能被打开、调整份数或改选配方版本，留下按旧计划
328			// 登记的投料。不能丢弃投料当作干净草稿，不能自动改状态，也
329			// 不能改选版本后继续。
330			if b.Status == StatusDraft && len(b.Feedings) > 0 {
331				return fmt.Errorf("%w: 批次 %q 仍为草稿状态，却存在 %d 条投料记录",
332					ErrCorruptData, b.BatchNo, len(b.Feedings))
333			}
334			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
335			if r == nil {
336				return fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
337					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
338			}
339			if err := validateBatchPlan(b, r); err != nil {
340				return err
341			}
342			if err := validateFeedings(b, r); err != nil {
343				return err
344			}
345		}
346		// 最后核对已保存的成功投料请求：请求记录里保存的返回结果必须能对应到
347		// 原请求批次中同序号的实际投料，并与原提交内容一致。必须先于一切按
348		// 请求编号重放结果的路径判断——否则重放会把与台账实际投料不符的保存
349		// 结果当成第一次成功登记的结果返回。
350		if err := validateFeedingRequests(st); err != nil {
351			return err
352		}
353		return nil
354	}
355	
356	// validateBatchPlan 检查一个已保存批次的计划份数与按绑定配方版本算出的
357	// 应投量。数量规则本身（正份数、千分之一克精度、逐物料上限）统一由
358	// planRequirements 实现，这里只补充“读取已保存批次”场景的错误分类与
359	// 批次编号：份数非正或应投量非法都属于 ErrCorruptData。
360	// 归属以批次实际绑定的版本为准：换用同编号的其他版本或许能算得通，也
361	// 不能作为接受依据。计划数量是否合法与投料无关：尚未投料、实投不足或
362	// 超出应投都不影响。
363	func validateBatchPlan(b *batchRecord, r *recipeRecord) error {
364		if b.PlannedPortions <= 0 {
365			return fmt.Errorf("%w: 批次 %q 的计划份数 %d 不是正整数",
366				ErrCorruptData, b.BatchNo, b.PlannedPortions)
367		}
368		if _, err := planRequirements(r, b.PlannedPortions); err != nil {
369			return fmt.Errorf("%w: 批次 %q 的%v", ErrCorruptData, b.BatchNo, err)
370		}
371		return nil
372	}
373	
374	// validatePlanForRecipe 校验创建或调整草稿批次时，给定份数按配方版本逐
375	// 物料计算的应投量都能精确表示到千分之一克且不超过上限。份数本身的正
376	// 整数检查由调用方按各自输入规则完成（调整草稿时份数传 0 表示不改份数，
377	// 走到这里的必是最终采用的正份数）；数量规则统一由 planRequirements
378	// 实现，这里透传其逐物料说明（物料、配方编号、版本、份数），由调用方
379	// 按本次提交包装为 ErrInvalidInput。
380	func validatePlanForRecipe(r *recipeRecord, portions int) error {
381		_, err := planRequirements(r, portions)
382		return err
383	}
384	
385	// validateFeedings 检查一个批次内已保存投料的登记顺序、合法性与配方归属。
386	// 归属以批次绑定的配方版本 r 为准：每条投料的物料编号必须在 r 的物料
387	// 列表中，否则整份台账视为损坏。数量方面只判断数量本身是否合法，不判断
388	// 实投是否符合配方：无投料的物料累计为零属正常，不足或超过应投量也不
389	// 在此拒绝。
390	//
391	// 序号是整个批次共用的一条登记序列：不同物料的投料依次共用这组序号，
392	// 不按物料各自另起编号；不同批次则各自从 1 开始。列表中第 i 条（位置
393	// 从 1 起）的保存序号必须恰好为 i——第一条必须为 1，此后每条加 1。
394	// 零、负数、漏号、重号、跳号，或只调换了记录位置却没有同步序号，都说明
395	// 记录已经失去登记先后次序，整份台账视为损坏，即使物料归属与数量全部
396	// 合法也不能接受。投料时间只由调用方填写、从不参与排序，因此不能用来
397	// 佐证或否定序号：同一时刻登记、后一条时间早于前一条都属正常。该校验
398	// 只读取现有序号与位置，绝不重排、补号或删除任何投料。
399	func validateFeedings(b *batchRecord, r *recipeRecord) error {
400		acc := newFeedingAccumulator()
401		for i, f := range b.Feedings {
402			// 位置 i+1 上的保存序号必须就是 i+1：先于归属与数量校验判断，
403			// 因为一旦序号与位置不符，调用方已经无法按序号区分这是哪一次
404			// 成功登记——按错误的序号继续核对物料与数量没有意义。不能挑
405			// 记录自带的序号当真、不能按投料时间重排，也不能自行补号或
406			// 删除后继续。空投料列表不会进入这里，不构成序号错误。
407			pos := i + 1
408			if f.Seq != pos {
409				return fmt.Errorf("%w: 批次 %q 投料列表第 %d 条记录的登记序号为 %d，应为 %d：登记序号必须从 1 起按保存位置逐条连续加 1，不能为零或负数、重号、漏号、跳号或与位置不符",
410					ErrCorruptData, b.BatchNo, pos, f.Seq, pos)
411			}
412			belongs := false
413			for _, m := range r.Materials {
414				if m.MaterialNo == f.MaterialNo {
415					belongs = true
416					break
417				}
418			}
419			if !belongs {
420				return fmt.Errorf("%w: 批次 %q 的第 %d 条投料物料 %q 不属于其绑定的配方 %q 版本 %q",
421					ErrCorruptData, b.BatchNo, f.Seq, f.MaterialNo, b.RecipeNo, b.RecipeVersion)
422			}
423			if f.GramsMilli <= 0 {
424				return fmt.Errorf("%w: 批次 %q 物料 %q 的第 %d 条投料数量不是正数",
425					ErrCorruptData, b.BatchNo, f.MaterialNo, f.Seq)
426			}
427			if !acc.add(f.MaterialNo, f.GramsMilli) {
428				return fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出上限 %s 克",
429					ErrCorruptData, b.BatchNo, f.MaterialNo, maxGramsMilli)
430			}
431		}
432		return nil
433	}
434	
435	// validateFeedingRequests 检查台账中每一条已保存的成功投料请求：请求记录里
436	// 保存的返回结果，必须对应原请求批次中确实存在的一条实际投料，且与该序号
437	// 记录的物料、克数、投料时间、登记人一致，并符合原提交内容。本次只核对
438	// 投料（addFeeding）请求，其他操作的保存结果不在此检查。
439	//
440	// 保存结果缺失、为 null、为空对象，或上述对应关系不成立（批次不存在、
441	// 序号在该批次中不存在、内容对不上），整份台账即视为损坏：不能仅凭保存
442	// 结果当作登记成功返回——重放取回的结果必须与批次查询显示的实际投料是同
443	// 一条。其他批次里同序号的投料不能作为对应记录；物料与数量相同但时间或
444	// 登记人不同也不算一致。核对只读取现有记录，绝不删除请求、补造投料或
445	// 重新执行原登记。
446	func validateFeedingRequests(st *persistedState) error {
447		for reqNo, req := range st.Requests {
448			if req == nil {
449				return fmt.Errorf("%w: 请求编号 %q 的请求记录为空", ErrCorruptData, reqNo)
450			}
451			if req.Op != opAddFeeding {
452				continue
453			}
454			if err := validateFeedingRequest(st, reqNo, req); err != nil {
455				return err
456			}
457		}
458		return nil
459	}
460	
461	// validateFeedingRequest 核对一条已保存的成功投料请求。对应关系分两层：
462	// 保存结果必须与批次中同序号的实际投料一致，也必须符合原提交内容（原
463	// 提交内容本身在登记时就来自同一次投料，两层一致才说明保存结果、实际
464	// 投料与原请求三者仍是同一次登记）。
465	//
466	// 数量按实际克数核对而非字符串写法：原请求填写 1.000、保存结果显示 1 是
467	// 同一次登记的正常写法差异；时间按同一时刻核对，不区分时区写法。这些
468	// 只影响读取核对，不改变请求内容的精确匹配规则——重放判定仍按提交内容
469	// 原文比较，把 1.000 改成 1 再提交仍是 ErrRequestConflict。
470	func validateFeedingRequest(st *persistedState, reqNo string, req *requestRecord) error {
471		var payload addFeedingPayload
472		if err := json.Unmarshal([]byte(req.Payload), &payload); err != nil {
473			return fmt.Errorf("%w: 投料请求 %q 保存的提交内容无法解析",
474				ErrCorruptData, reqNo)
475		}
476		batchNo := payload.BatchNo
477		if len(req.Result) == 0 {
478			return fmt.Errorf("%w: 投料请求 %q（批次 %q）缺少保存的登记结果",
479				ErrCorruptData, reqNo, batchNo)
480		}
481		var result FeedingView
482		if err := json.Unmarshal(req.Result, &result); err != nil {
483			return fmt.Errorf("%w: 投料请求 %q（批次 %q）保存的登记结果无法解析",
484				ErrCorruptData, reqNo, batchNo)
485		}
486		// 原请求对应的批次必须存在：批次都没有了，保存的结果不能单独作为
487		// 登记成功的依据。
488		b := findBatch(st, batchNo)
489		if b == nil {
490			return fmt.Errorf("%w: 投料请求 %q 对应的批次 %q 不存在，保存的登记结果不能单独作为登记成功的依据",
491				ErrCorruptData, reqNo, batchNo)
492		}
493		// 登记序号必须在原请求对应的批次中确实存在：只在该批次的投料列表里
494		// 找，其他批次里同序号的投料不能作为对应记录。序号为零或负数、超出
495		// 该批次投料条数（含保存结果为 null 或空对象得到的零值）都会在这里
496		// 被拒绝。
497		var rec *feedingRecord
498		for i := range b.Feedings {
499			if b.Feedings[i].Seq == result.Seq {
500				rec = &b.Feedings[i]
501				break
502			}
503		}
504		if rec == nil {
505			return fmt.Errorf("%w: 投料请求 %q 保存结果的登记序号 %d 在批次 %q 中不存在",
506				ErrCorruptData, reqNo, result.Seq, batchNo)
507		}
508		// 克数按实际数值核对：保存结果与原提交内容的写法可以不同（1.000 与 1），
509		// 但换算成实际克数必须一致；无法解析的克数写法本身就是损坏。
510		resultGrams, err := parseGrams(result.Grams)
511		if err != nil {
512			return fmt.Errorf("%w: 投料请求 %q（批次 %q）保存结果的克数 %q 不合法",
513				ErrCorruptData, reqNo, batchNo, result.Grams)
514		}
515		payloadGrams, err := parseGrams(payload.Grams)
516		if err != nil {
517			return fmt.Errorf("%w: 投料请求 %q（批次 %q）保存的提交内容克数 %q 不合法",
518				ErrCorruptData, reqNo, batchNo, payload.Grams)
519		}
520		// 保存结果必须与该序号的实际投料一致：物料编号、实际克数、投料时间
521		// （同一时刻，不区分时区写法）、登记人逐项核对——不能仅凭物料和数量
522		// 相同就忽略时间或登记人的差异。
523		if result.MaterialNo != rec.MaterialNo || resultGrams != rec.GramsMilli ||
524			!result.Time.Equal(rec.Time) || result.Registrar != rec.Registrar {
525			return fmt.Errorf("%w: 投料请求 %q 保存的结果与批次 %q 第 %d 条实际投料不一致（物料、克数、投料时间或登记人不符）",
526				ErrCorruptData, reqNo, batchNo, rec.Seq)
527		}
528		// 保存结果还必须符合原提交内容：同样按物料、实际克数、同一时刻、
529		// 登记人核对。
530		if result.MaterialNo != payload.MaterialNo || resultGrams != payloadGrams ||
531			!result.Time.Equal(payload.Time) || result.Registrar != payload.Registrar {
532			return fmt.Errorf("%w: 投料请求 %q 保存的结果与原提交内容（批次 %q）不一致（物料、克数、投料时间或登记人不符）",
533				ErrCorruptData, reqNo, batchNo)
534		}
535		return nil
536	}
537	
538	// persist 先写临时文件再原子改名，并 fsync 目录，保证已提交数据可恢复。
539	func (s *Store) persist(st *persistedState) error {
540		data, err := json.MarshalIndent(st, "", "  ")
541		if err != nil {
542			return err
543		}
544		tmpPath := filepath.Join(s.dir, stateFileName+".tmp")
545		f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
546		if err != nil {
547			return err
548		}
549		if _, err := f.Write(data); err != nil {
550			f.Close()
551			return err
552		}
553		if err := f.Sync(); err != nil {
554			f.Close()
555			return err
556		}
557		if err := f.Close(); err != nil {
558			return err
559		}
560		if err := os.Rename(tmpPath, filepath.Join(s.dir, stateFileName)); err != nil {
561			return err
562		}
563		if d, err := os.Open(s.dir); err == nil {
564			_ = d.Sync()
565			_ = d.Close()
566		}
567		return nil
568	}
569	
570	func cloneState(st *persistedState) (*persistedState, error) {
571		data, err := json.Marshal(st)
572		if err != nil {
573			return nil, err
574		}
575		var out persistedState
576		if err := json.Unmarshal(data, &out); err != nil {
577			return nil, err
578		}
579		if out.Requests == nil {
580			out.Requests = map[string]*requestRecord{}
581		}
582		return &out, nil
583	}
584	
585	// write 是所有写入操作的统一入口：
586	//   - reqNo 为空直接报错；
587	//   - 同一 reqNo 且操作与内容完全相同，返回第一次成功的结果（幂等重放）；
588	//   - 同一 reqNo 用于其他操作或不同内容，返回 ErrRequestConflict；
589	//   - apply 在状态副本上执行，返回校验错误时不落盘、不占用请求编号；
590	//   - apply 成功后，状态与请求记录一起原子落盘，再切换到内存状态。
591	func (s *Store) write(reqNo, op string, payload any, apply func(*persistedState) (json.RawMessage, error), out any) error {
592		if reqNo == "" {
593			return errors.New("请求编号不能为空")
594		}
595		s.mu.Lock()
596		defer s.mu.Unlock()
597		if err := s.lockExclusive(); err != nil {
598			return err
599		}
600		defer s.unlock()
601	
602		// 跨进程场景下，其他进程可能已提交新数据；加锁后重新加载，
603		// 确保在最新状态上应用变更，避免用旧快照覆盖其他进程的写入。
604		if err := s.load(); err != nil {
605			return err
606		}
607	
608		payloadRaw, err := json.Marshal(payload)
609		if err != nil {
610			return err
611		}
612		payloadStr := string(payloadRaw)
613	
614		if req, ok := s.state.Requests[reqNo]; ok {
615			if req.Op != op || req.Payload != payloadStr {
616				return fmt.Errorf("%w: 请求编号 %q 已用于操作 %q，不能再用于操作 %q 或不同内容",
617					ErrRequestConflict, reqNo, req.Op, op)
618			}
619			// 保存的投料结果已在本次 load 的 validateState 中与对应批次的实际
620			// 投料核对一致（缺失、为 null、为空对象或内容不符都已在上面拒绝），
621			// 这里取回的就是第一次成功登记的那条投料。
622			if err := json.Unmarshal(req.Result, out); err != nil {
623				return fmt.Errorf("重放请求 %q 的结果失败: %w", reqNo, err)
624			}
625			return nil
626		}
627	
628		clone, err := cloneState(s.state)
629		if err != nil {
630			return err
631		}
632		result, err := apply(clone)
633		if err != nil {
634			return err
635		}
636		clone.Requests[reqNo] = &requestRecord{Op: op, Payload: payloadStr, Result: result}
637		if err := s.persist(clone); err != nil {
638			return fmt.Errorf("保存台账失败: %w", err)
639		}
640		s.state = clone
641		if err := json.Unmarshal(result, out); err != nil {
642			return fmt.Errorf("解析请求结果失败: %w", err)
643		}
644		return nil
645	}
646	
647	// read 在共享锁下读取当前状态。
648	func (s *Store) read(fn func(*persistedState) error) error {
649		s.mu.Lock()
650		defer s.mu.Unlock()
651		if err := s.lockShared(); err != nil {
652			return err
653		}
654		defer s.unlock()
655		if err := s.load(); err != nil {
656			return err
657		}
658		return fn(s.state)
659	}
660	
661	// 视图构造：每次都从记录全新构造，返回的切片与内部状态完全隔离。
662	
663	func buildRecipeView(r *recipeRecord) *RecipeView {
664		mats := make([]MaterialView, 0, len(r.Materials))
665		for _, m := range r.Materials {
666			mats = append(mats, MaterialView{MaterialNo: m.MaterialNo, Grams: m.GramsMilli.String()})
667		}
668		return &RecipeView{RecipeNo: r.RecipeNo, Version: r.Version, Name: r.Name, Materials: mats}
669	}
670	
671	func buildBatchView(b *batchRecord, r *recipeRecord) (*BatchView, error) {
672		v := &BatchView{
673			BatchNo:         b.BatchNo,
674			RecipeNo:        r.RecipeNo,
675			RecipeVersion:   r.Version,
676			RecipeName:      r.Name,
677			PlannedPortions: b.PlannedPortions,
678			Status:          b.Status,
679			Feedings:        make([]FeedingView, 0, len(b.Feedings)),
680			Materials:       make([]MaterialRequirement, 0, len(r.Materials)),
681		}
682	
683		for _, f := range b.Feedings {
684			v.Feedings = append(v.Feedings, FeedingView{
685				Seq:        f.Seq,
686				MaterialNo: f.MaterialNo,
687				Grams:      f.GramsMilli.String(),
688				Time:       f.Time,
689				Registrar:  f.Registrar,
690			})
691		}
692	
693		// 按物料累计实投量；台账在读取时已通过 validateFeedings 校验，
694		// 这里仍用同一套累计规则防一手整数回绕。
695		acc := newFeedingAccumulator()
696		for _, f := range b.Feedings {
697			if !acc.add(f.MaterialNo, f.GramsMilli) {
698				return nil, fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出可表示范围",
699					ErrCorruptData, b.BatchNo, f.MaterialNo)
700			}
701		}
702	
703		// 数量核对按配方物料逐项列出；应投量统一由 planRequirements 按本批次
704		// 绑定版本与计划份数计算，与创建、调整、读取校验共用同一套规则。
705		// 台账在读取时已通过 validateState 校验，这里仍防一手同一版本内物料
706		// 编号重复，避免返回重复的数量核对项。
707		required, err := planRequirements(r, b.PlannedPortions)
708		if err != nil {
709			return nil, fmt.Errorf("%w: 批次 %q 的%v", ErrCorruptData, b.BatchNo, err)
710		}
711		seen := make(map[string]bool, len(required))
712		for _, item := range required {
713			if seen[item.materialNo] {
714				return nil, fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
715					ErrCorruptData, r.RecipeNo, r.Version, item.materialNo)
716			}
717			seen[item.materialNo] = true
718			act := acc.total(item.materialNo)
719			v.Materials = append(v.Materials, MaterialRequirement{
720				MaterialNo:      item.materialNo,
721				RequiredGrams:   item.requiredGrams.String(),
722				ActualGrams:     act.String(),
723				DifferenceGrams: (act - item.requiredGrams).String(),
724			})
725		}
726		return v, nil
727	}
728	
729	// recipeKey 是配方的唯一标识：配方编号与版本号的组合，采用精确匹配。
730	type recipeKey struct {
731		recipeNo string
732		version  string
733	}
734	
735	func findRecipe(st *persistedState, recipeNo, version string) *recipeRecord {
736		for _, r := range st.Recipes {
737			if r.RecipeNo == recipeNo && r.Version == version {
738				return r
739			}
740		}
741		return nil
742	}
743	
744	func findBatch(st *persistedState, batchNo string) *batchRecord {
745		for _, b := range st.Batches {
746			if b.BatchNo == batchNo {
747				return b
748			}
749		}
750		return nil
751	}
752

