71	
72	// corruptFeedingRequestResult 把正常台账内容中 feed-1 请求的保存结果替换为
73	// mutate 给出的值（mutate 返回 nil 表示删除该字段），返回改写后的文件内容。
74	func corruptFeedingRequestResult(t *testing.T, good []byte, mutate func() json.RawMessage) []byte {
75		t.Helper()
