102	// 已保存的成功投料请求的结果缺失、为 null、为空对象，或被替换成另一条投料、
103	// 指向批次中不存在的序号、内容（物料、克数、时间、登记人）与实际投料或原
104	// 提交内容不符时，Open 必须返回 ErrCorruptData：错误信息指出问题请求编号
105	// 及关联批次，不返回可用的台账对象，也不改写原文件。
106	func TestOpenRejectsCorruptFeedingRequestResult(t *testing.T) {
