174	// 原请求对应的批次不存在时，保存的结果不能单独作为登记成功的依据：
175	// 即使结果本身内容完整、与其他批次的某条投料完全吻合，也按损坏处理。
176	func TestOpenRejectsFeedingRequestResultWhenBatchMissing(t *testing.T) {
