151			t.Fatalf("幂等重放应成功: %v", err)
152		}
153		assertRegisteredRecipeV1(t, replay)
154	}
155	
156	// 配方查询结果隔离：先取得两份查询结果，对其中一份改名称、改物料内容、
157	// 追加、清空，另一份保持原内容；两份都改坏之后，后续查询仍得到完整配方，
158	// 不出现被改过的物料、漏项或额外物料。
159	func TestRecipeQueryResultCopyIsolation(t *testing.T) {
160		s := openTestStore(t)
161		if _, err := s.RegisterRecipe("req-register", "R1", "v1", "配方一", isoBaseMaterials()); err != nil {
162			t.Fatalf("登记配方失败: %v", err)
163		}
164	
165		first, err := s.GetRecipe("R1", "v1")
166		if err != nil {
167			t.Fatal(err)
168		}
169		second, err := s.GetRecipe("R1", "v1")
170		if err != nil {
171			t.Fatal(err)
172		}
173	
174		// 整理先取得的这一份。
175		first.Name = "本地改名"
176		first.Materials[0].MaterialNo = "M9"
177		first.Materials[0].Grams = "777"
178		first.Materials[1].Grams = "888"
179		first.Materials = append(first.Materials, MaterialView{MaterialNo: "M5", Grams: "5"})
180	
181		// 先取得的另一份查询结果应保持原内容，不与第一份共享底层数组。
182		assertRegisteredRecipeV1(t, second)
183	
184		// 清空第一份，台账与第二份仍不受影响。
185		first.Materials = nil
186		assertRegisteredRecipeV1(t, second)
187	
188		// 再把第二份也清空并追加一个本地物料、改本地名称。
189		second.Materials = second.Materials[:0]
190		second.Materials = append(second.Materials, MaterialView{MaterialNo: "MX", Grams: "1"})
191		second.Name = "另一个本地名"
192		if len(second.Materials) != 1 || second.Materials[0].MaterialNo != "MX" {
193			t.Fatalf("本地整理应当真的只作用于手中对象，得到 %+v", second.Materials)
194		}
195	
196		// 后续查询仍得到完整配方：M1=100、M2=0.5，顺序不变，无 MX/M5/M9。
197		third, err := s.GetRecipe("R1", "v1")
198		if err != nil {
199			t.Fatal(err)
200		}
201		assertRegisteredRecipeV1(t, third)
202	}
203	
204	// 配方是批次投料依据：原版本为每份 M1=100 克、M2=0.5 克，批次计划 3 份。
205	// 调用方把手中配方里的 M1 改成其他编号/克数并追加物料后：
206	//   - 既有批次仍列出 M1 应投 300 克、M2 应投 1.5 克，未投料的 M2 仍显示；
207	//   - 已登记的实际投料与差额仍按原版本核对，本地变化不会重新解释物料；
208	//   - 改过的编号 M9 不能用于投料（ErrMaterialNotInRecipe）；
209	//   - 此后新建、绑定同一版本的批次同样采用已登记内容；
210	//   - 关闭重开后，落盘内容仍是登记时的版本与投料。
211	func TestBatchRequirementsUseRegisteredRecipeVersion(t *testing.T) {
212		dir := t.TempDir()
213		s, err := Open(dir)
214		if err != nil {
215			t.Fatalf("Open(%q) 失败: %v", dir, err)
216		}
217		held, err := s.RegisterRecipe("req-register", "R1", "v1", "配方一", isoBaseMaterials())
218		if err != nil {
219			t.Fatalf("登记配方失败: %v", err)
220		}
221		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 3); err != nil {
222			t.Fatalf("创建既有批次失败: %v", err)
223		}
224		if _, err := s.StartBatch("s1", "B1"); err != nil {
225			t.Fatalf("开始执行失败: %v", err)
226		}
227		fixedTime := time.Date(2026, 2, 3, 10, 0, 0, 0, time.UTC)
228		// M1 应投 300 克，先投 250 克（欠 50）；M2 不投料。
229		if _, err := s.AddFeeding("f1", "B1", "M1", "250", fixedTime, "张三"); err != nil {
230			t.Fatalf("登记 M1 投料失败: %v", err)
231		}
232	
233		// 调用方把“手中配方”改得面目全非：M1 换编号、换克数，M2 换克数，
234		// 追加一项，改名称。
235		held.Materials[0].MaterialNo = "M9"
236		held.Materials[0].Grams = "999"
237		held.Materials[1].Grams = "888"
238		held.Materials = append(held.Materials, MaterialView{MaterialNo: "M5", Grams: "5"})
239		held.Name = "本地改名"
240	
241		// 本地改成 M9 不会让台账接受 M9 投料：归属仍按登记版本解释。
242		if _, err := s.AddFeeding("f-bad", "B1", "M9", "10", fixedTime, "张三"); !errors.Is(err, ErrMaterialNotInRecipe) {
243			t.Fatalf("本地改名后的 M9 不应属于登记版本，应返回 ErrMaterialNotInRecipe，得到 %v", err)
244		}
245	
246		assertExistingBatch := func(t *testing.T, st *Store) {
247			t.Helper()
248			got, err := st.GetBatch("B1")
249			if err != nil {
250				t.Fatalf("查询批次失败: %v", err)
251			}
252			if got.RecipeNo != "R1" || got.RecipeVersion != "v1" || got.RecipeName != "配方一" {
253				t.Fatalf("批次绑定的配方信息不应改变，得到 %q %q %q", got.RecipeNo, got.RecipeVersion, got.RecipeName)
254			}
255			if len(got.Materials) != 2 {
256				t.Fatalf("应只列出登记版本的 2 项物料（无 M9/M5，M2 不漏），得到 %+v", got.Materials)
257			}
258			m := materialsMap(got)
259			// 应投 100×3=300，实投仍是登记的 250，差额 -50。
260			checkRequirement(t, m, "M1", "300", "250", "-50")
261			// 应投 0.5×3=1.5，未投料仍显示，实投 0，差额 -1.5。
262			checkRequirement(t, m, "M2", "1.5", "0", "-1.5")
263			if len(got.Feedings) != 1 {
264				t.Fatalf("被拒绝的 M9 投料不应落账，得到 %d 条投料", len(got.Feedings))
265			}
266			f := got.Feedings[0]
267			if f.Seq != 1 || f.MaterialNo != "M1" || f.Grams != "250" {
268				t.Fatalf("已登记投料不应被本地变化重新解释，得到 %+v", f)
269			}
270		}
271		assertExistingBatch(t, s)
272	
273		// 此后新建、绑定同一已登记版本的批次，仍按 M1=100、M2=0.5 计应投。
274		if _, err := s.CreateBatch("b2", "B2", "R1", "v1", 3); err != nil {
275			t.Fatalf("本地整理后新建批次应仍能绑定登记版本: %v", err)
276		}
277		got2, err := s.GetBatch("B2")
278		if err != nil {
279			t.Fatal(err)
280		}
281		if got2.RecipeName != "配方一" || len(got2.Materials) != 2 {
282			t.Fatalf("新批次应采用登记版本，得到 %+v", got2)
283		}
284		m2 := materialsMap(got2)
285		checkRequirement(t, m2, "M1", "300", "0", "-300")
286		checkRequirement(t, m2, "M2", "1.5", "0", "-1.5")
287	
288		// 关闭重开：丢弃全部本地对象后，台账内容仍是登记时的版本与投料。
289		if err := s.Close(); err != nil {
290			t.Fatalf("关闭台账失败: %v", err)
291		}
292		s3, err := Open(dir)
293		if err != nil {
294			t.Fatalf("重新打开台账失败: %v", err)
295		}
296		defer s3.Close()
297		reopenedRecipe, err := s3.GetRecipe("R1", "v1")
298		if err != nil {
299			t.Fatal(err)
300		}
301		assertRegisteredRecipeV1(t, reopenedRecipe)
302		assertExistingBatch(t, s3)
303	}
304	
305	// 版本间隔离：同一配方编号可以有多个版本，两个版本即使使用相同物料编号，
306	// 每份克数也各自独立。改动一个版本的返回对象，既不能影响另一个版本的查询
307	// 结果，也不能让绑定各版本的批次改用另一版本的用量。
308	func TestRecipeVersionViewsIndependent(t *testing.T) {
309		s := openTestStore(t)
310		if _, err := s.RegisterRecipe("rv1", "R1", "v1", "配方初版", []MaterialInput{
311			{MaterialNo: "M1", Grams: "100"},
312			{MaterialNo: "M2", Grams: "0.5"},
313		}); err != nil {
314			t.Fatalf("登记 v1 失败: %v", err)
315		}
316		// v2 也使用 M1，但每份 250 克；另有 M4=2 克。
317		if _, err := s.RegisterRecipe("rv2", "R1", "v2", "配方改版", []MaterialInput{
318			{MaterialNo: "M1", Grams: "250"},
319			{MaterialNo: "M4", Grams: "2"},
320		}); err != nil {
321			t.Fatalf("登记 v2 失败: %v", err)
322		}
323	
324		v1, err := s.GetRecipe("R1", "v1")
325		if err != nil {
326			t.Fatal(err)
327		}
328		v2, err := s.GetRecipe("R1", "v2")
329		if err != nil {
330			t.Fatal(err)
331		}
332	
333		// 对 v1 的返回对象做破坏性整理：M1 改编号、改克数，M2 改克数，追加，清空。
334		v1.Name = "本地改名"
335		v1.Materials[0].MaterialNo = "M9"
336		v1.Materials[0].Grams = "999"
337		v1.Materials[1].Grams = "888"
338		v1.Materials = append(v1.Materials, MaterialView{MaterialNo: "M5", Grams: "5"})
339		v1.Materials = nil
340	
341		// v2 手里的对象不受影响：仍是 M1=250、M4=2。
342		assertRecipeViewExactly(t, v2, "R1", "v2", "配方改版", []MaterialView{
343			{MaterialNo: "M1", Grams: "250"},
344			{MaterialNo: "M4", Grams: "2"},
345		})
346		// v1 重新查询仍是登记内容。
347		again1, err := s.GetRecipe("R1", "v1")
348		if err != nil {
349			t.Fatal(err)
350		}
351		assertRecipeViewExactly(t, again1, "R1", "v1", "配方初版", []MaterialView{
352			{MaterialNo: "M1", Grams: "100"},
353			{MaterialNo: "M2", Grams: "0.5"},
354		})
355	
356		// 两个批次分别绑定两个版本：相同编号 M1 的应投量各按各的版本计算。
357		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 3); err != nil {
358			t.Fatal(err)
359		}
360		if _, err := s.CreateBatch("b2", "B2", "R1", "v2", 2); err != nil {
361			t.Fatal(err)
362		}
363	
364		// 再整理手里的 v2：把 M1 改成 1 克并追加物料。
365		v2.Materials[0].Grams = "1"
366		v2.Materials = append(v2.Materials, MaterialView{MaterialNo: "M6", Grams: "6"})
367		v2.Name = "本地改版名"
368	
369		b1, err := s.GetBatch("B1")
370		if err != nil {
371			t.Fatal(err)
372		}
373		b2, err := s.GetBatch("B2")
374		if err != nil {
375			t.Fatal(err)
376		}
377		if b1.RecipeName != "配方初版" || b2.RecipeName != "配方改版" {
378			t.Fatalf("批次不应采用被本地改名的版本: %q / %q", b1.RecipeName, b2.RecipeName)
379		}
380		mb1 := materialsMap(b1)
381		if len(mb1) != 2 {
382			t.Fatalf("v1 批次应只含 M1、M2，得到 %+v", b1.Materials)
383		}
384		checkRequirement(t, mb1, "M1", "300", "0", "-300") // 100×3，不借 v2 的 250
385		checkRequirement(t, mb1, "M2", "1.5", "0", "-1.5")
386		mb2 := materialsMap(b2)
387		if len(mb2) != 2 {
388			t.Fatalf("v2 批次应只含 M1、M4，得到 %+v", b2.Materials)
389		}
390		checkRequirement(t, mb2, "M1", "500", "0", "-500") // 250×2，不借 v1 的 100，也不是本地改的 1
391		checkRequirement(t, mb2, "M4", "4", "0", "-4")     // 2×2
392	
393		// 两个版本再查一次，均为登记内容，互不串改。
394		last1, err := s.GetRecipe("R1", "v1")
395		if err != nil {
396			t.Fatal(err)
397		}
398		last2, err := s.GetRecipe("R1", "v2")
399		if err != nil {
400			t.Fatal(err)
401		}
402		assertRecipeViewExactly(t, last1, "R1", "v1", "配方初版", []MaterialView{
403			{MaterialNo: "M1", Grams: "100"},
404			{MaterialNo: "M2", Grams: "0.5"},
405		})
406		assertRecipeViewExactly(t, last2, "R1", "v2", "配方改版", []MaterialView{
407			{MaterialNo: "M1", Grams: "250"},
408			{MaterialNo: "M4", Grams: "2"},
409		})
410	}
411	
412	// 本地改动不等于正式提交：
413	//   - 用“同一请求编号 + 改过的内容”再提交，是 ErrRequestConflict（不同内容），
414	//     不会借幂等通道覆盖；
415	//   - 用“新的请求编号”把改过的内容再次登记到已存在的配方编号+版本号，
416	//     无论改名称、改克数、改编号、换序、替换、追加、删减，乃至内容本身非法，
417	//     都先撞上“版本已存在”，统一返回 ErrRecipeExists。
418	// 原版本与引用它的批次始终保持原样。
419	func TestResubmitModifiedContentStillExists(t *testing.T) {
420		s := openTestStore(t)
421		if _, err := s.RegisterRecipe("req-first", "R1", "v1", "配方一", isoBaseMaterials()); err != nil {
422			t.Fatalf("登记配方失败: %v", err)
423		}
424		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 3); err != nil {
425			t.Fatalf("创建批次失败: %v", err)
426		}
427	
428		// 同一请求编号配改过的内容：按请求冲突拒绝，而不是覆盖或重放。
429		tampered := []MaterialInput{
430			{MaterialNo: "M1", Grams: "200"},
431			{MaterialNo: "M2", Grams: "0.5"},
432		}
433		if _, err := s.RegisterRecipe("req-first", "R1", "v1", "配方一", tampered); !errors.Is(err, ErrRequestConflict) {
434			t.Fatalf("同编号不同内容应返回 ErrRequestConflict，得到 %v", err)
435		}
436	
437		// 新请求编号 + 各种改过（甚至非法）的内容再次登记到 R1/v1：一律 ErrRecipeExists。
438		cases := []struct {
439			name       string
440			recipeName string
441			materials  []MaterialInput
442		}{
443			{"改每份克数", "配方一", []MaterialInput{
444				{MaterialNo: "M1", Grams: "200"},
445				{MaterialNo: "M2", Grams: "0.5"},
446			}},
447			{"改物料编号", "配方一", []MaterialInput{
448				{MaterialNo: "MX", Grams: "100"},
449				{MaterialNo: "M2", Grams: "0.5"},
450			}},
451			{"改配方名称", "配方改名", isoBaseMaterials()},
452			{"调整物料顺序", "配方一", []MaterialInput{
453				{MaterialNo: "M2", Grams: "0.5"},
454				{MaterialNo: "M1", Grams: "100"},
455			}},
456			{"替换其中一项", "配方一", []MaterialInput{
457				{MaterialNo: "M1", Grams: "100"},
458				{MaterialNo: "M7", Grams: "7"},
459			}},
460			{"追加物料", "配方一", []MaterialInput{
461				{MaterialNo: "M1", Grams: "100"},
462				{MaterialNo: "M2", Grams: "0.5"},
463				{MaterialNo: "M3", Grams: "3"},
464			}},
465			{"删减物料", "配方一", []MaterialInput{
466				{MaterialNo: "M1", Grams: "100"},
467			}},
468			{"内容非法_物料编号重复", "配方一", []MaterialInput{
469				{MaterialNo: "M1", Grams: "1"},
470				{MaterialNo: "M1", Grams: "2"},
471			}},
472		}
473		for i, tc := range cases {
474			t.Run(tc.name, func(t *testing.T) {
475				reqNo := fmt.Sprintf("req-again-%d", i)
476				if _, err := s.RegisterRecipe(reqNo, "R1", "v1", tc.recipeName, tc.materials); !errors.Is(err, ErrRecipeExists) {
477					t.Fatalf("改过的内容再次登记到已存在版本应返回 ErrRecipeExists，得到 %v", err)
478				}
479			})
480		}
481	
482		// 原版本内容不变。
483		got, err := s.GetRecipe("R1", "v1")
484		if err != nil {
485			t.Fatal(err)
486		}
487		assertRegisteredRecipeV1(t, got)
488	
489		// 引用它的批次仍按登记版本核对：M1=300、M2=1.5，均无投料。
490		batch, err := s.GetBatch("B1")
491		if err != nil {
492			t.Fatal(err)
493		}
494		if batch.RecipeName != "配方一" || len(batch.Materials) != 2 {
495			t.Fatalf("批次应保持绑定登记版本，得到 %+v", batch)
496		}
497		m := materialsMap(batch)
498		checkRequirement(t, m, "M1", "300", "0", "-300")
499		checkRequirement(t, m, "M2", "1.5", "0", "-1.5")
500	}
