15	func openTestStore(t *testing.T) *Store {
16		t.Helper()
17		dir := t.TempDir()
18		s, err := Open(dir)
19		if err != nil {
20			t.Fatalf("Open(%q) 失败: %v", dir, err)
21		}
22		t.Cleanup(func() { s.Close() })
23		return s
24	}
