26	func registerStandardRecipe(t *testing.T, s *Store, reqNo string) {
27		t.Helper()
28		_, err := s.RegisterRecipe(reqNo, "R1", "v1", "标准配方", []MaterialInput{
29			{MaterialNo: "M1", Grams: "100"},
30			{MaterialNo: "M2", Grams: "0.5"},
31			{MaterialNo: "M3", Grams: "0.010"},
32		})
33		if err != nil {
34			t.Fatalf("登记配方失败: %v", err)
35		}
36	}
