69	func TestRegisterRecipeAndGet(t *testing.T) {
70		s := openTestStore(t)
71		view, err := s.RegisterRecipe("r1", "R1", "v1", "配方一", []MaterialInput{
72			{MaterialNo: "M1", Grams: "100"},
73			{MaterialNo: "M2", Grams: "0.500"},
