82			t.Fatalf("物料视图不正确: %+v", view.Materials)
83		}
84	
85		got, err := s.GetRecipe("R1", "v1")
86		if err != nil {
87			t.Fatalf("查询配方失败: %v", err)
88		}
89		if got.Name != "配方一" || len(got.Materials) != 2 {
90			t.Fatalf("查询结果不正确: %+v", got)
91		}
92	
93		// 同一配方编号的不同版本可以登记。
94		if _, err := s.RegisterRecipe("r2", "R1", "v2", "配方二", nil); !errors.Is(err, ErrInvalidInput) {
95			t.Fatalf("无物料登记应返回 ErrInvalidInput，得到 %v", err)
96		}
97		if _, err := s.RegisterRecipe("r2", "R1", "v2", "配方二", []MaterialInput{
98			{MaterialNo: "M1", Grams: "2"},
99		}); err != nil {
100			t.Fatalf("登记不同版本失败: %v", err)
101		}
102	
103		// 已登记版本不可覆盖。
104		if _, err := s.RegisterRecipe("r3", "R1", "v1", "改名", []MaterialInput{
105			{MaterialNo: "M1", Grams: "1"},
106		}); !errors.Is(err, ErrRecipeExists) {
107			t.Fatalf("覆盖已登记版本应返回 ErrRecipeExists，得到 %v", err)
108		}
109	}
