111	func TestRegisterRecipeValidation(t *testing.T) {
112		s := openTestStore(t)
113		cases := []struct {
114			name       string
115			recipeNo   string
116			version    string
117			recipeName string
118			materials  []MaterialInput
119		}{
120			{"空配方编号", "", "v1", "n", []MaterialInput{{MaterialNo: "M1", Grams: "1"}}},
121			{"空版本号", "R1", "", "n", []MaterialInput{{MaterialNo: "M1", Grams: "1"}}},
122			{"空名称", "R1", "v1", "", []MaterialInput{{MaterialNo: "M1", Grams: "1"}}},
123			{"无物料", "R1", "v1", "n", nil},
124			{"物料编号为空", "R1", "v1", "n", []MaterialInput{{MaterialNo: "", Grams: "1"}}},
125			{"物料编号重复", "R1", "v1", "n", []MaterialInput{{MaterialNo: "M1", Grams: "1"}, {MaterialNo: "M1", Grams: "2"}}},
126			{"克数为零", "R1", "v1", "n", []MaterialInput{{MaterialNo: "M1", Grams: "0"}}},
127			{"克数为负", "R1", "v1", "n", []MaterialInput{{MaterialNo: "M1", Grams: "-1"}}},
128			{"克数四位小数", "R1", "v1", "n", []MaterialInput{{MaterialNo: "M1", Grams: "1.2345"}}},
129			{"克数为空", "R1", "v1", "n", []MaterialInput{{MaterialNo: "M1", Grams: ""}}},
130			{"克数非法字符", "R1", "v1", "n", []MaterialInput{{MaterialNo: "M1", Grams: "abc"}}},
131			{"克数多位小数点", "R1", "v1", "n", []MaterialInput{{MaterialNo: "M1", Grams: "1.2.3"}}},
132		}
133		for _, tc := range cases {
134			t.Run(tc.name, func(t *testing.T) {
135				_, err := s.RegisterRecipe("req-"+tc.name, tc.recipeNo, tc.version, tc.recipeName, tc.materials)
136				if !errors.Is(err, ErrInvalidInput) {
137					t.Fatalf("应返回 ErrInvalidInput，得到 %v", err)
138				}
139			})
140		}
141	}
