283		if _, err := s.StartBatch("s4", "B9"); !errors.Is(err, ErrNotFound) {
284			t.Fatalf("开始不存在的批次应返回 ErrNotFound，得到 %v", err)
285		}
286		if _, err := s.CloseBatch("c3", "B9"); !errors.Is(err, ErrNotFound) {
287			t.Fatalf("关闭不存在的批次应返回 ErrNotFound，得到 %v", err)
288		}
289	}
